import re
def grep(r, i, kws, w=400):
    r=json.loads(r) if isinstance(r,str) else r
    x=r[i]; c=x['content']; print("#####",x['title'],x['url'])
    for k in kws:
        for m in list(re.finditer(k,c,re.I))[:2]:
            print(" ..",c[max(0,m.start()-w):m.end()+w].replace("\n"," ")); print()
